\begin{enumerate}
\item For any $\xi\in\Xi$, $\dim\Lambda_{(r_i),I}^{\xi}\leq d_{(r_i),I}$.
\item Equality holds in \textup{(1)} 
for a unique $\xi$: the corresponding stratum consists
of those $(u_i,A_i,B_i)$ such that $A_i$ is injective and $B_i$ is surjective for all $i$,
and $u_{i+1}\notin\mathrm{im}(A_i)$ for all $i\in I$.
\item If $\dim \Lambda^\xi_{(r_i),I} = d_{(r_i),I}-1$, then $\Lambda^\xi_{(r_i),I} \subset \Lambda^\circ$.
\end{enumerate}
